// Asegurarnos que exista binary
if (!items[0].binary || !items[0].binary.data) {
  throw new Error('No binary data found');
}

const filename = $json.filename || 'cv.pdf';

// Reescribimos metadata del archivo
items[0].binary.data.mimeType = 'application/pdf';
items[0].binary.data.fileName = filename;

return items;

const data = $input.all().map(item => item.json);
data.sort((a, b) => new Date(b.fecha_evaluacion) - new Date(a.fecha_evaluacion));

const stats = {
  total: data.length,
  contratar: data.filter(d => d.puntaje >= 7).length,
  considerar: data.filter(d => d.puntaje > 5 && d.puntaje < 7).length,
  noRecomendable: data.filter(d => d.puntaje <= 5).length,
  promedioGeneral: data.length > 0 ? (data.reduce((sum, d) => sum + (Number(d.puntaje) || 0), 0) / data.length).toFixed(1) : '0.0'
};

function getRecomendacionClass(puntaje) {
  if (puntaje >= 7) return 'contratar';
  if (puntaje > 5) return 'considerar';
  return 'no-recomendable';
}

function getRecomendacionText(puntaje) {
  if (puntaje >= 7) return 'Contratar';
  if (puntaje > 5) return 'Considerar';
  return 'No Recomendable';
}

function getBadgeColor(puntaje) {
  if (puntaje >= 7) return '#10b981';
  if (puntaje > 5) return '#f59e0b';
  return '#ef4444';
}

function escapeHtml(text) {
  if (!text) return '';
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;')
    .replace(/\n/g, ' ')
    .replace(/\r/g, '');
}

const WEBHOOK_OBSERVACIONES_URL = 'https://n8n.calzalindo.com.ar/webhook/update_observaciones';
const WEBHOOK_ESTADO_URL        = 'https://n8n.calzalindo.com.ar/webhook/update_estado';
const WEBHOOK_RECHAZO_URL       = 'https://n8n.calzalindo.com.ar/webhook/rechazo_cliente';

// Obtener puestos únicos para el filtro
const puestosUnicos = [...new Set(data.map(d => d.puesto).filter(p => p && p !== 'N/A'))].sort();
const opcionesPuestos = puestosUnicos.map(p => `<option value="${escapeHtml(p.toLowerCase())}">${escapeHtml(p)}</option>`).join('');

var html = `
