    const recordId = r.id || '';
    const nombreEscapado = escapeHtml(r.nombre || 'Desconocido');
    const textoEscapado = escapeHtml(r.cv_texto || 'Sin texto');
    const obsEscapadas = escapeHtml(r.observaciones || '');
